package calc

type Point struct {
	X, Y int64
}

func abs(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

func manhattan(a, b Point) int64 {
	return abs(a.X-b.X) + abs(a.Y-b.Y)
}

package calc

import "testing"

func TestRecords(t *testing.T) {
	if got := manhattan(Point{1, 2}, Point{4, -2}); got != 7 {
		t.Errorf("manhattan(Point{1, 2}, Point{4, -2}) = %d, want 7", got)
	}
	if got := manhattan(Point{0, 0}, Point{0, 0}); got != 0 {
		t.Errorf("manhattan(Point{0, 0}, Point{0, 0}) = %d, want 0", got)
	}
}
